package com.bonbio.service;
import com.bonbio.dto.Dtos.*; import com.bonbio.entity.*; import com.bonbio.repository.*; import org.springframework.stereotype.Service;
@Service public class RecetteService { private final RecetteRepository repo; private final ProduitRepository produits; public RecetteService(RecetteRepository repo,ProduitRepository produits){this.repo=repo;this.produits=produits;} public RecetteResponse get(Long produitId){return repo.findByProduitId(produitId).map(r->new RecetteResponse(r.getId(),produitId,r.getContenu())).orElse(new RecetteResponse(null,produitId,""));} public RecetteResponse save(Long produitId,RecetteRequest req){Produit p=produits.findById(produitId).orElseThrow(()->new RuntimeException("Produit introuvable."));Recette r=repo.findByProduitId(produitId).orElseGet(Recette::new);r.setProduit(p);r.setContenu(req.contenu());r=repo.save(r);return new RecetteResponse(r.getId(),produitId,r.getContenu());} }
